import { createRoute, z } from '@hono/zod-openapi'

const InventoryAggregatorSchema: z.ZodType<InventoryAggregatorType> = z
  .lazy(() =>
    z
      .object({
        Expression: InventoryAggregatorExpressionSchema.and(
          z
            .any()
            .openapi({ description: 'The inventory type and attribute name for aggregation.' }),
        ).exactOptional(),
        Aggregators: InventoryAggregatorListSchema.and(
          z
            .any()
            .openapi({
              description:
                'Nested aggregators to further refine aggregation for an inventory type.',
            }),
        ).exactOptional(),
        Groups: InventoryGroupListSchema.and(
          z
            .any()
            .openapi({
              description:
                "A user-defined set of one or more filters on which to aggregate inventory data. Groups return a count of resources that match and don't match the specified criteria.",
            }),
        ).exactOptional(),
      })
      .openapi({
        description: 'Specifies the inventory type and attribute for the aggregation execution.',
        required: [],
      }),
  )
  .openapi('InventoryAggregator')

type InventoryAggregatorListType = z.infer<typeof InventoryAggregatorSchema>[]

const OpsFilterKeySchema = z.string().min(1).max(200).openapi('OpsFilterKey')

const OpsFilterValueSchema = z.string().min(0).max(256).openapi('OpsFilterValue')

const OpsFilterValueListSchema = z
  .array(OpsFilterValueSchema)
  .min(1)
  .max(40)
  .openapi('OpsFilterValueList')

const OpsFilterOperatorTypeSchema = z
  .enum(['Equal', 'NotEqual', 'BeginWith', 'LessThan', 'GreaterThan', 'Exists'])
  .openapi('OpsFilterOperatorType')

const OpsFilterSchema = z
  .object({
    Key: OpsFilterKeySchema.and(z.any().openapi({ description: 'The name of the filter.' })),
    Values: OpsFilterValueListSchema.and(z.any().openapi({ description: 'The filter value.' })),
    Type: OpsFilterOperatorTypeSchema.and(
      z.any().openapi({ description: 'The type of filter.' }),
    ).exactOptional(),
  })
  .openapi({ required: ['Key', 'Values'], description: 'A filter for viewing OpsData summaries.' })
  .openapi('OpsFilter')

type OpsFilterListType = z.infer<typeof OpsFilterSchema>[]

const OpsAggregatorSchema: z.ZodType<OpsAggregatorType> = z
  .lazy(() =>
    z
      .object({
        AggregatorType: OpsAggregatorTypeSchema.and(
          z
            .any()
            .openapi({
              description:
                'Either a <code>Range</code> or <code>Count</code> aggregator for limiting an OpsData summary.',
            }),
        ).exactOptional(),
        TypeName: OpsDataTypeNameSchema.and(
          z
            .any()
            .openapi({ description: 'The data type name to use for viewing counts of OpsData.' }),
        ).exactOptional(),
        AttributeName: OpsDataAttributeNameSchema.and(
          z
            .any()
            .openapi({
              description:
                'The name of an OpsData attribute on which to limit the count of OpsData.',
            }),
        ).exactOptional(),
        Values: OpsAggregatorValueMapSchema.and(
          z.any().openapi({ description: 'The aggregator value.' }),
        ).exactOptional(),
        Filters: OpsFilterListSchema.and(
          z.any().openapi({ description: 'The aggregator filters.' }),
        ).exactOptional(),
        Aggregators: OpsAggregatorListSchema.and(
          z.any().openapi({ description: 'A nested aggregator for viewing counts of OpsData.' }),
        ).exactOptional(),
      })
      .openapi({
        description:
          'One or more aggregators for viewing counts of OpsData using different dimensions such as <code>Source</code>, <code>CreatedTime</code>, or <code>Source and CreatedTime</code>, to name a few.',
        required: [],
      }),
  )
  .openapi('OpsAggregator')

type OpsAggregatorListType = z.infer<typeof OpsAggregatorSchema>[]

type InventoryAggregatorExpressionType = string

const InventoryGroupNameSchema = z.string().min(1).max(200).openapi('InventoryGroupName')

const InventoryFilterKeySchema = z.string().min(1).max(200).openapi('InventoryFilterKey')

const InventoryFilterValueSchema = z.string().openapi('InventoryFilterValue')

const InventoryFilterValueListSchema = z
  .array(InventoryFilterValueSchema)
  .min(1)
  .max(40)
  .openapi('InventoryFilterValueList')

const InventoryQueryOperatorTypeSchema = z
  .enum(['Equal', 'NotEqual', 'BeginWith', 'LessThan', 'GreaterThan', 'Exists'])
  .openapi('InventoryQueryOperatorType')

const InventoryFilterSchema = z
  .object({
    Key: InventoryFilterKeySchema.and(
      z.any().openapi({ description: 'The name of the filter key.' }),
    ),
    Values: InventoryFilterValueListSchema.and(
      z
        .any()
        .openapi({
          description:
            'Inventory filter values. Example: inventory filter where managed node IDs are specified as values <code>Key=AWS:InstanceInformation.InstanceId,Values= i-a12b3c4d5e6g, i-1a2b3c4d5e6,Type=Equal</code>. ',
        }),
    ),
    Type: InventoryQueryOperatorTypeSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The type of filter.</p> <note> <p>The <code>Exists</code> filter must be used with aggregators. For more information, see <a href="https://docs.aws.amazon.com/systems-manager/latest/userguide/sysman-inventory-aggregate.html">Aggregating inventory data</a> in the <i>Amazon Web Services Systems Manager User Guide</i>.</p> </note>',
        }),
    ).exactOptional(),
  })
  .openapi({
    required: ['Key', 'Values'],
    description: 'One or more filters. Use a filter to return a more specific list of results.',
  })
  .openapi('InventoryFilter')

const InventoryFilterListSchema = z
  .array(InventoryFilterSchema)
  .min(1)
  .max(5)
  .openapi('InventoryFilterList')

const InventoryGroupSchema = z
  .object({
    Name: InventoryGroupNameSchema.and(z.any().openapi({ description: 'The name of the group.' })),
    Filters: InventoryFilterListSchema.and(
      z
        .any()
        .openapi({
          description:
            "Filters define the criteria for the group. The <code>matchingCount</code> field displays the number of resources that match the criteria. The <code>notMatchingCount</code> field displays the number of resources that don't match the criteria. ",
        }),
    ),
  })
  .openapi({
    required: ['Name', 'Filters'],
    description:
      "A user-defined set of one or more filters on which to aggregate inventory data. Groups return a count of resources that match and don't match the specified criteria.",
  })
  .openapi('InventoryGroup')

type InventoryGroupListType = z.infer<typeof InventoryGroupSchema>[]

const InventoryAggregatorExpressionSchema: z.ZodType<InventoryAggregatorExpressionType> = z
  .string()
