const InventoryAggregatorListSchema: z.ZodType<InventoryAggregatorListType> = z
  .lazy(() => z.array(InventoryAggregatorSchema).min(1).max(10))
  .openapi('InventoryAggregatorList')

const InventoryGroupListSchema: z.ZodType<InventoryGroupListType> = z
  .array(InventoryGroupSchema)
  .min(1)
  .max(15)
