const InventoryItemTypeNameSchema = z
  .string()
  .regex(/^(AWS|Custom):.*$/)
  .min(1)
  .max(100)
  .openapi('InventoryItemTypeName')

const InventoryItemSchemaVersionSchema = z
  .string()
  .regex(/^([0-9]{1,6})(\.[0-9]{1,6})$/)
  .openapi('InventoryItemSchemaVersion')

const InventoryItemCaptureTimeSchema = z
  .string()
  .regex(
    /^(20)[0-9][0-9]-(0[1-9]|1[012])-([12][0-9]|3[01]|0[1-9])(T)(2[0-3]|[0-1][0-9])(:[0-5][0-9])(:[0-5][0-9])(Z)$/,
  )
  .openapi('InventoryItemCaptureTime')

const InventoryItemContentHashSchema = z.string().max(256).openapi('InventoryItemContentHash')

const AttributeValueSchema = z.string().min(0).max(4096).openapi('AttributeValue')

const InventoryItemEntrySchema = z
  .record(z.string(), AttributeValueSchema)
  .refine((val) => Object.keys(val).length >= 0)
  .refine((val) => Object.keys(val).length <= 50)
  .openapi('InventoryItemEntry')

const InventoryItemEntryListSchema = z
  .array(InventoryItemEntrySchema)
  .min(0)
  .max(10000)
  .openapi('InventoryItemEntryList')

const InventoryItemContentContextSchema = z
  .record(z.string(), AttributeValueSchema)
  .refine((val) => Object.keys(val).length >= 0)
  .refine((val) => Object.keys(val).length <= 50)
  .openapi('InventoryItemContentContext')

type InventoryItemType = {
  TypeName: z.infer<typeof InventoryItemTypeNameSchema> & { [key: string]: unknown }
  SchemaVersion: z.infer<typeof InventoryItemSchemaVersionSchema> & { [key: string]: unknown }
  CaptureTime: z.infer<typeof InventoryItemCaptureTimeSchema> & { [key: string]: unknown }
  ContentHash?: z.infer<typeof InventoryItemContentHashSchema> & { [key: string]: unknown }
  Content?: z.infer<typeof InventoryItemEntryListSchema> & { [key: string]: unknown }
  Context?: z.infer<typeof InventoryItemContentContextSchema> & { [key: string]: unknown }
}

